def gcd(a, b):
    """Greatest common divisor using Euclid's algorithm."""
    while a:
        a, b = (b % a, a)
    return b

def _t():
    assert gcd(10, 12) == 2, ('assertEqual', gcd(10, 12), 2)
    assert gcd(10, 15) == 5, ('assertEqual', gcd(10, 15), 5)
    assert gcd(10, 11) == 1, ('assertEqual', gcd(10, 11), 1)
    assert gcd(100, 15) == 5, ('assertEqual', gcd(100, 15), 5)
    assert gcd(-10, 2) == -2, ('assertEqual', gcd(-10, 2), -2)
    assert gcd(10, -2) == 2, ('assertEqual', gcd(10, -2), 2)
    assert gcd(-10, -2) == -2, ('assertEqual', gcd(-10, -2), -2)
    for i in range(1, 20):
        for j in range(1, 20):
            assert gcd(i, j) > 0, ('assertTrue', gcd(i, j) > 0)
            assert gcd(-i, j) < 0, ('assertTrue', gcd(-i, j) < 0)
            assert gcd(i, -j) > 0, ('assertTrue', gcd(i, -j) > 0)
            assert gcd(-i, -j) < 0, ('assertTrue', gcd(-i, -j) < 0)
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')
